#!/bin/sh
# Install the staged CDE greeter files (binaries, stock background, unit, PAM files) as root.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/greeter-install.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'greeter-install.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -eu
umask 022

usage() {
	cat <<'USAGE'
Usage: greeter-install.sh [--help|-h] [--build|--version] [--rollback] [--dest-root DIR]

Install the greeter files staged beside this script (the deploy stages them and prints
the command to run, as `sudo <staging dir>/cde-greeter-install`):

  crucible, cde-login    -> /opt/cde/bin/            root:root 0755 (previous copy kept as .prev)
  stock.png              -> /opt/cde/share/backgrounds/stock.png   0644
  dist/systemd/cde-login.service -> /etc/systemd/system/           0644
  dist/pam.d/cde-login, dist/pam.d/cde-login-greeter -> /etc/pam.d/ 0644

Runs only as root and only when /opt/cde exists. Both staged binaries must answer
--build with this script's own build id before anything is written. Each file is
written beside its target and renamed into place; a file that already matches (bytes,
mode, owner) is left alone, so a second run changes nothing. `systemctl daemon-reload`
runs at the end of every successful install. It never restarts, enables, disables or
stops a unit: when cde-login or the unit changed it prints the one manual next step
(`systemctl restart cde-login.service`, which ends the running session).

Options:
  --rollback       copy crucible.prev and cde-login.prev back over the installed
                   binaries (both must exist; the .prev files are kept)
  --dest-root DIR  test option: install under DIR instead of /, create missing
                   directories, and skip the root check, ownership and systemctl
  --build, --version  print this script's build id and exit
  -h, --help       print this help and exit (needs no root)

Exit status: 0 on success; 1 on a refusal or failure (`greeter-install: <reason>` on
stderr); 2 on bad usage.
USAGE
}

here=$(dirname "$(readlink -f "$0")")

# Installed-copy stamp: the deploy generates cde-greeter-install from this file with the guard
# path rewritten, stamped_id set and the build-id.sh source line replaced.
# shellcheck disable=SC2034
stamped_id=
# shellcheck source-path=SCRIPTDIR source=lib/build-id.sh
. "$here/lib/build-id.sh"

for a in "$@"; do
	case $a in
		--help | -h) usage; exit 0 ;;
	esac
done
build_flags "$0" "$@"

die() {
	echo "greeter-install: $*" >&2
	exit 1
}

rollback=0
dest_root=
while [ $# -gt 0 ]; do
	case $1 in
		--rollback) rollback=1; shift ;;
		--dest-root)
			[ $# -ge 2 ] || { echo "greeter-install: --dest-root needs a directory" >&2; exit 2; }
			dest_root=$2
			shift 2
			;;
		*) echo "greeter-install: unknown argument: $1" >&2; usage >&2; exit 2 ;;
	esac
done

if [ -n "$stamped_id" ]; then my_id=$stamped_id; else my_id=$(build_id "$0"); fi

real=1
[ -z "$dest_root" ] || real=0
if [ "$real" -eq 1 ]; then
	[ "$(id -u)" -eq 0 ] || die "must run as root (try: sudo $0)"
fi

opt=$dest_root/opt/cde
bin=$opt/bin
bgdir=$opt/share/backgrounds
unitdir=$dest_root/etc/systemd/system
pamdir=$dest_root/etc/pam.d
[ -d "$opt" ] || die "$opt does not exist (create it as root first; see docs/greeter.md)"

done_list=
note_done() { done_list=${done_list:+$done_list, }$1; }
fail() { die "$1; already replaced: ${done_list:-none}"; }

# replace <src> <dst> <mode>: write beside the target, set mode (and owner), rename into place.
replace() {
	_tmp=$(mktemp "$(dirname "$2")/.greeter-install.XXXXXX") || fail "cannot create a temp file beside $2"
	if [ "$real" -eq 1 ]; then
		install -o root -g root -m "$3" "$1" "$_tmp" || { rm -f "$_tmp"; fail "cannot write $2"; }
	else
		install -m "$3" "$1" "$_tmp" || { rm -f "$_tmp"; fail "cannot write $2"; }
	fi
	mv -f "$_tmp" "$2" || { rm -f "$_tmp"; fail "cannot rename into $2"; }
}

# meta_ok <file> <mode>: the mode (and, in a real run, root:root ownership) already match.
meta_ok() {
	[ "$(stat -c %a "$1")" = "$2" ] || return 1
	[ "$real" -eq 0 ] || [ "$(stat -c %u:%g "$1")" = 0:0 ] || return 1
}

changed=
restart=0

# put <src> <dst> <mode> <label> <restart? 0|1> <keep prev? 0|1>
put() {
	if [ -f "$2" ] && cmp -s "$1" "$2"; then
		meta_ok "$2" "$3" && return 0
		chmod "$3" "$2" || fail "cannot set the mode of $2"
		if [ "$real" -eq 1 ]; then chown root:root "$2" || fail "cannot chown $2"; fi
		echo "fixed mode/owner: $2"
	else
		if [ "$6" -eq 1 ] && [ -e "$2" ]; then
			cp -p "$2" "$2.prev" || fail "cannot write $2.prev"
		fi
		replace "$1" "$2" "$3"
		echo "installed: $2"
	fi
	note_done "$4"
	changed=1
	[ "$5" -eq 0 ] || restart=1
}

if [ "$rollback" -eq 1 ]; then
	for n in crucible cde-login; do
		[ -f "$bin/$n.prev" ] || die "nothing to roll back: $bin/$n.prev is missing (nothing was touched)"
	done
	for n in crucible cde-login; do
		if [ -f "$bin/$n" ] && cmp -s "$bin/$n.prev" "$bin/$n" && meta_ok "$bin/$n" 755; then continue; fi
		replace "$bin/$n.prev" "$bin/$n" 755
		echo "restored: $bin/$n"
		note_done "$n"
		[ "$n" != cde-login ] || restart=1
	done
	[ -n "$done_list" ] || echo "greeter-install: nothing to do (the installed binaries already equal the .prev pair)"
	[ "$restart" -eq 0 ] || echo "next step (ends the running session): systemctl restart cde-login.service"
	exit 0
fi

# Preflight: every source present and both binaries on this script's build id, before any write.
for f in crucible cde-login stock.png dist/systemd/cde-login.service dist/pam.d/cde-login dist/pam.d/cde-login-greeter; do
	[ -f "$here/$f" ] || die "missing staged file: $here/$f (nothing was touched)"
done
for n in crucible cde-login; do
	[ -x "$here/$n" ] || die "staged $here/$n is not executable (nothing was touched)"
	got=$("$here/$n" --build 2>&1) || die "staged $n --build failed: $got (nothing was touched)"
	[ "$got" = "$my_id" ] || die "staged $n --build printed '$got', expected $my_id (nothing was touched)"
done
if [ "$real" -eq 1 ]; then
	[ -d "$unitdir" ] || die "$unitdir does not exist (nothing was touched)"
	[ -d "$pamdir" ] || die "$pamdir does not exist (nothing was touched)"
else
	mkdir -p "$unitdir" "$pamdir" || die "cannot create $unitdir and $pamdir"
fi
mkdir -p "$bin" "$bgdir" || die "cannot create $bin and $bgdir"

put "$here/crucible" "$bin/crucible" 755 crucible 0 1
put "$here/cde-login" "$bin/cde-login" 755 cde-login 1 1
put "$here/stock.png" "$bgdir/stock.png" 644 stock.png 0 0
put "$here/dist/systemd/cde-login.service" "$unitdir/cde-login.service" 644 cde-login.service 1 0
put "$here/dist/pam.d/cde-login" "$pamdir/cde-login" 644 pam-cde-login 0 0
put "$here/dist/pam.d/cde-login-greeter" "$pamdir/cde-login-greeter" 644 pam-cde-login-greeter 0 0

if [ "$real" -eq 1 ]; then
	systemctl daemon-reload || fail "systemctl daemon-reload failed"
fi
[ -n "$changed" ] || echo "greeter-install: nothing to do (all files current)"
[ "$restart" -eq 0 ] || echo "next step (ends the running session): systemctl restart cde-login.service"
